import 'dart:async';
class AuthUser { const AuthUser(this.id, this.email); final String id; final String email; }
class AuthSession { const AuthSession(this.user, this.accessToken, this.expiresAt); final AuthUser user; final String accessToken; final DateTime expiresAt; }
abstract interface class AuthRemote { Future<AuthSession> login(String email, String password); Future<AuthSession> register(String email, String password); Future<AuthSession?> refresh(); Future<void> logout(); }
abstract interface class AuthRepository { Future<AuthSession> login(String email, String password); Future<AuthSession> register(String email, String password); Future<AuthSession?> restore(); Future<void> logout(); }
class RemoteAuthRepository implements AuthRepository { RemoteAuthRepository(this._remote); final AuthRemote _remote; @override Future<AuthSession> login(String e,String p)=>_remote.login(e,p); @override Future<AuthSession> register(String e,String p)=>_remote.register(e,p); @override Future<AuthSession?> restore()=>_remote.refresh(); @override Future<void> logout()=>_remote.logout(); }
class AuthState { const AuthState({this.session, this.loading=false}); final AuthSession? session; final bool loading; bool get authenticated => session != null; AuthState copyWith({AuthSession? session, bool? loading, bool clear=false})=>AuthState(session: clear?null:session??this.session,loading:loading??this.loading); }
class AuthNotifier { AuthNotifier(this._repository); final AuthRepository _repository; AuthState state=const AuthState(); Future<void>? _restoreFuture; Future<void> restore()=>_restoreFuture??= _restore(); Future<void> _restore() async { try { state=state.copyWith(loading:true); state=AuthState(session:await _repository.restore()); } finally {_restoreFuture=null;} } Future<void> logout() async { await _repository.logout(); state=state.copyWith(clear:true); } }
